    public void LastDateOfQuarter_WhenDefinitionIsInvalidAndQuarterIsValid_ShouldThrowExactly()
    {
        var definition = (CalendarQuarterDefinition)999;

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = DateOnlyExtensions.GetLastDateOfQuarter(2025, 1, definition);
        });
    }

    /// <summary>
    /// Verifies that <see cref="DateOnly.MinValue" /> yields <c>0001-03-31</c> (end of Q1 of year 1) for the January-to-December quarter end.
    /// </summary>
    [TestMethod]
    public void LastDateOfQuarter_WhenInputIsMinValue_ShouldReturnExpectedDate()
    {
        var actual = DateOnly.MinValue.LastDateOfQuarter(CalendarQuarterDefinition.JanuaryToDecember);
        Assert.AreEqual(new DateOnly(1, 3, 31), actual);
    }

